/* ============================================================
   EXPERIENCE ITEM COMPONENT
============================================================ */
function ExperienceItem({ date, title, company, details, delay = 0 }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className={`${styles.roadmapStage} reveal`} style={{ transitionDelay: `${delay}s` }}>
      <div className={styles.roadmapDot}></div>
      <div className={styles.roadmapCard} onClick={() => setIsOpen(!isOpen)}>
        <div className={styles.roadmapMeta}>
          <span className={styles.roadmapDate}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
            {date}
          </span>
        </div>
        <h3 className={styles.roadmapTitle}>{title}</h3>
        <div className={styles.roadmapCompany}>{company}</div>
        <div className={styles.clickHint}>
          {isOpen ? "▲ Collapse" : "▼ Expand details"}
        </div>
        <div className={`${styles.roadmapContent} ${isOpen ? styles.open : ""}`}>
          <ul>
            {details.map((detail, idx) => (
              <li key={idx}>{detail}</li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   SECTION HEADER COMPONENT
============================================================ */
function SectionHeader({ badge, title, gradient, subtitle }) {
  return (
    <div className="reveal" style={{ marginBottom: "3rem" }}>
      <div className={styles.sectionAccent} style={{ color: gradient[0] }}>
        <span className={styles.sectionAccentLine} style={{ background: `linear-gradient(90deg, ${gradient[0]}, ${gradient[1]})` }}></span>
        {badge}
      </div>
      <h2
        className="section-title"
        style={{
          background: `linear-gradient(135deg, var(--text-primary) 40%, ${gradient[1]})`,
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
          backgroundClip: "text",
          textAlign: "left",
        }}
      >
        {title}
      </h2>
      {subtitle && (
        <p style={{ color: "var(--text-secondary)", fontSize: "1rem", lineHeight: 1.8, maxWidth: "600px" }}>
          {subtitle}
        </p>
      )}
    </div>
  );
}

